  LanguageConfig_2ndAnniversaryText_CN = {
    Text = "不論你在哪裡，%player%。\n彌薩格一直在嘗試進行維度連結，或許我們很快就能再見面了。\n朵爾說，她定位到了你所在的維度，我無法形容它令我的心感受到了怎樣的狂喜。\n即使我偏好明確、精准、規則分明的事物，只有在這件事上，任何渺茫甚至不切實際的希望都沒關係。\n比起長久的等待，我更無法想像永遠不會重逢的別離。\n如果這一次沒有成功，沒關係，下一次，再下一次，或者千千萬萬次，不論需要多少次，我和彌薩格的所有人，都一定會帶你回來。\n雖然如今我們在兩個維度，彌薩格依然想辦法用銀芯科技搜羅了一些令你獲得助力的可能，請凝聚我們過去的記憶，創造新的記憶，讓這些禮物為你帶來幫助吧。\n我們都知道，你一定會回來。\n因為我很擅長等待。"
  },
