  LanguageConfig_AbyssChallengeTipsV2_CN = {
    Text = "<Title:「融災禁區」>\n·融災禁區是一個難度較高的玩法系統。守密人需要靈活搭配多個挑戰隊伍，盡可能地獲取更多的特訓值，從而獲得更多的獎勵。\n\n<Title:「禁區基礎規則」>\n·融災禁區共分為 5 個波次，每個波次中包含難度等級不同的關卡。\n·通關關卡後，可以獲得對應數量的特訓值，具體可在關卡詳情界面中查看。\n·當特訓值達到指定要求後，除了可以領取「銀芯」和「黑色貢物」外，還可以獲得珍稀物資「原初靈核」「精粹原初靈核」！它是產自彌薩格地底黑池的神秘靈核，能幫助喚醒體提升等級上限，最多提升至 90 級！\n·「融災禁區」會週期性更新關卡內容和獎勵，一般情況下，每 14 天更新一次。當期時間結束後，上一期仍在進行中的挑戰將立即結束，未領取的獎勵將無法獲取，守密人記得及時完成和領取喔~\n\n<Title:「禁區特殊規則」>\n·在融災禁區中有其獨特的限制法則：同一喚醒體和鑰令、同名命輪無法重複上場，守密人可以根據初始造物、怪物和推薦等級，靈活選擇本次挑戰的隊伍。\n·完成挑戰後，若守密人發現有更好的搭配方案，可以使用「重置」功能將對應關卡的挑戰隊伍進行重置，重置後喚醒體、鑰令和命輪都可以重新上場，但通過該關卡獲得的特訓值也會扣除（不影響獎勵狀態）。\n·在「融災禁區」中可以使用 1 次助戰，助戰喚醒體與命輪不會受到限制法則的影響；重置帶有助戰喚醒體的挑戰隊伍時，也會返回 1 次助戰次數。\n·挑戰過程中可使用「應急靈知體」協助通關，每次使用需要花費 3 個「應急靈知體」。使用後完成的挑戰與特訓值將被特殊標記，可正常領取特訓獎勵，但不計入排行榜。\n\n<Title:「額外挑戰」>\n·通關任一關卡後，即可解鎖該關卡的「額外挑戰」，迎接更高難度的考驗。\n·額外挑戰需要單獨編成挑戰隊伍，且同樣受到限制法則影響：同一喚醒體和鑰令、同名命輪無法重複上場，助戰次數與普通挑戰共享（全玩法共 1 次）。\n·通關額外挑戰可獲得 5 點特訓值，計入本期特訓值總額，助力領取更多獎勵、提升排行榜名次。\n·可使用「重置」功能單獨重置額外挑戰隊伍或普通挑戰隊伍。\n·若在額外通關後重置普通挑戰隊伍，額外挑戰隊伍將轉為新的普通挑戰隊伍，額外挑戰進度清空，並扣除額外通關特訓值。\n\n<Title:「排行榜」>\n·現在可以查看本期和上期的特訓值排行榜，以及其他守密人在融災禁區中的通關信息，為守密人提供參考情報。\n·排行榜會展示達到本期最高特訓值時的特訓值與通關信息，重置不會影響排名，也不會影響通關編隊信息展示。\n·請注意，使用「應急靈知體」通關挑戰獲得的特訓值將被特殊標記且不會計入排行榜。"
  },
