    Text = "·在進行融蝕之墟、禁忌纂錄、幻夢深潛、超驗存在等玩法時，可以選擇使用1名已互相關注守密人的助戰喚醒體進行出戰。\n·助戰喚醒體需滿足當前編隊的界域限制，不符合條件的助戰喚醒體無法上場，守密人可以返回調整編隊後再進行上場。\n·部分活動可能會有額外的特殊助戰規則，請查看該活動的「活動說明」進行詳細了解。"
