  LanguageConfig_AwakerFavorability_Description_Detail_CN = {
    Text = "<Title:【同調率獲取】>\n·通關調查行動、特遣紀錄、意識潛游和幻夢深潛等關卡後，上陣喚醒體可以獲得同調率。\n·喚醒體出牌越多、消耗算力和狂氣越多，獲得的同調率越多；關卡推薦等級越高，獲得的同調率也越多。\n·守密人銀鑰能量消耗越多，上陣喚醒體獲得的同調率也越多。\n·手動戰鬥期間獲得的同調率為開啟「自動戰鬥」時的 3 倍。\n·使用助戰通關關卡後，守密人的上陣喚醒體獲得同調率提高 50%。\n·邀請喚醒體進入宿舍後，每 5 分鐘可獲得 1 點同調率。\n·離線儲存超過 300 點後，獲取速度降為每 15 分鐘 1 點，最多可儲存至 3000 點。\n\n<Title:【同調率等級】>\n·收集喚醒體的同調率可以提升同調率等級，等級越高可解鎖更多喚醒體的語音和故事，部分等級還可獲得「無垢之芯」。\n·喚醒體同調率達到 Lv15 後，可通過「靈肉同調」消耗「同心之證」將等級上限逐級提升至 Lv20，每級可獲得「精粹靈核碎片」×5，提升至 Lv20 時還可額外獲得「曜閃」。\n·喚醒體同調率達到當前等級上限後將不再繼續累積，需先完成靈肉同調才能繼續獲取。"
