  LanguageConfig_BPRuleTxt2_CN = {
    Text = "\n\n<Title:【特殊課題】>\n·本期課題週期為{s1} - {s2}（GMT+8），完成任務獲取雙倍課題經驗，助力課題等級快速提升。"
  },
  LanguageConfig_BPRuleTxt_CN = {
    Text = "<Title:【課題類別】>\n·每期課題中，基礎課題預設解鎖獲取，守密人還可透過解鎖高階課題，獲取更豐厚的獎勵。\n·通常每期課題會持續 28 天，有時候彌薩格會開啟持續時間更短的特殊課題，特殊課題期間獲取到的課題經驗都會翻倍，助力守密人更快完成當期課題！\n \n·持續 28 天的課題：\n  ·解鎖「高階課題」需要「源液」×680，可立即獲得 「銀芯」×680。\n  ·解鎖「核心課題」需要「源液」×1280，可立即獲得「銀芯」×1460。\n  ·將「高級課題」升級為「核心課題」需要「源液」×780，可立即獲得「銀芯」×780。\n \n·特殊課題：\n  ·課題期間獲得的「課題經驗」翻倍。\n  ·解鎖「高階課題」需要「源液」×680，可立即獲得 「銀芯」×680。\n  ·解鎖「核心課題」需要「源液」×980，可立即獲得「銀芯」×1070。\n  ·將「高級課題」升級為「核心課題」需要「源液」×390，可立即獲得「銀芯」×390。\n\n<Title:【核心課題特權】>\n·解鎖「核心課題」後，可以在本期課題持續期間獲得特權。\n·在「日常試訓」的「基礎活性離子」累積獎勵中獲得的「現實起點」、「無垢之芯」、「經驗」、「銀芯」提升至 3 倍。購買「核心課題」後會補發本期已領取的「基礎活性離子」累積獎勵的額外倍率部分。\n·可以在戰鬥中使用「時序逆行」返回經歷過的回合。\n·可以在「相位對弈」中限時解鎖所有卡牌。\n\n<Title:【課題等級】>\n·守密人可透過完成密境課室的日常試訓和週常試訓來獲取課題經驗，提高課題等級，獲取豐厚獎勵。\n·「日常試訓」將在9點刷新，「週常試訓」將在每週一9點(UTC+8)刷新。\n·課題等級達到50級後，每提升1級，可獲得1份額外獎勵。"
  },
