  LanguageConfig_BPTaskTab_CN = {Text = "任務"},
  LanguageConfig_BPTimeFormat_CN = {
    Text = "本期剩餘{s1}"
  },
  LanguageConfig_BacktrackAwaker_Rules_CN = {
    Text = "<Title:【養成回溯】>\n·此操作將重置喚醒體的所有升級、升格、技能、靈知深化狀態，消耗的材料與金券均會全數返還。\n·喚醒體所有消耗的界域升格素材，返還為等同數量與稀有度的「初階升格匣子」、「中階升格匣子」、「高階升格匣子」，可以選擇等同數量與稀有度的任意界域升格素材。\n·喚醒體所有消耗的界域技能素材，返還為等同數量與稀有度的「初階技能補給」、「中階技能補給」、「高階技能補給」，可以選擇等同數量與稀有度的任意界域技能素材。\n·喚醒體所有消耗的「幸運糖果」、「蠟像泥胚」、「漆黑鎖扣」、「維度結晶」、「虔誠聖心」，返還為30倍數量的「擬態凝晶」。 \n<Title:【啟靈回溯】>\n·此操作將重置喚醒體的啟靈狀態，並重置啟靈帶來的等級上限，消耗的材料會全數返還。\n·喚醒體所有消耗或未使用的啟靈殘片，將視獲取來源分別返還成不同的道具。\n·由「原型視界」兌換所得的，返還為「原型視界」。\n·由限時喚醒所得的限定喚醒體轉化而來的，返還為「靈魂回溯之芯」。\n·「朵爾」「奧吉爾」「蘿坦」將會返回「調查徽章」× 2500。\n·「拉蒙娜」「環行·拉蒙娜」將會返回「殘片·拉蒙娜」。\n·「艾繼絲」「奧瑞塔」「艾瑞卡」將會返回「融蝕之珠」× 8000。\n·透過其他方式所得的，返還為「原質樂園」。\n<Title:【黑池歸還】>\n·此操作除了「養成回溯」所有效果之外，還將喚醒體本身也重置，變為未解鎖狀態。\n·喚醒體所裝備的命輪、密契都將卸下，其頭像將會變為不可用，如果正在使用會切換為預設頭像。\n·喚醒體的升格獎勵領取狀態、同調率與同調率獎勵領取狀態均將保留，重新獲取該喚醒體時會繼承。\n·喚醒體本身將視來源分別返還成不同的道具。由限時喚醒所得的限定喚醒體，返還為「靈魂回溯之芯」；透過其他方式所得的，返還為「原質樂園」。\n<Title:【物品說明】>\n·「初階升格匣子」：使用時可任選純白殘片、淬製本能、記憶副本、認知模板中其中1個。\n·「中階升格匣子」：使用時可任選純白文書、淬製理智、情感副本、精神模板中其中1個。\n·「高階升格匣子」：使用時可任選純白秘篇、淬製心靈、意識副本、靈知模板中其中1個。\n·「初階技能補給」：使用時可任選失色晶蝶、低莖海百合、風乾蟲蛹、殘破礦晶中其中1個。\n·「中階技能補給」：使用時可任選閃耀晶蝶、高莖海百合、原生蟲蛹、隕星碎塊中其中1個。\n·「高階技能補給」：使用時可任選混沌結晶、尤因他百合、芽孢聚合物、尤卡坦之星中其中1個。\n·「原型視界」：使用時可從中任選1個已解鎖SSR角色的喚醒體殘片。\n·「原質樂園」：使用時可從中任選1個「界域研習」中的喚醒體喚醒。\n·「靈魂回溯之芯」：使用時可從中任選1個「界域研習」、往期角色活動喚醒和當期角色活動喚醒中的喚醒體。"
  },
