  },
  LanguageConfig_BacktrackWeapon_Rules_CN = {
    Text = "<Title:【疊位回溯】>\n·此操作將重置命輪所有疊位狀態，消耗的材料會全數返還。\n·通過「循環母版」啟動的疊位，返還「循環母版」；通過限時喚醒所得的限定命輪啟動的疊位，返還「命途回溯之芯」；通過其他方式啟動的疊位，返還為「輪轉之書」。\n<Title:【黑池歸還】>\n·此操作除了「養成回溯」所有效果之外，還將命輪本身也重置。\n·通過限時喚醒所得的限定命輪，返還「命途回溯之芯」；通過其他方式所得的，返還為「輪轉之書」。\n<Title:【物品說明】>\n·以下物品均在物資介面中使用。\n·「循環母版」：可以作為任意一個SSR命輪的疊位素材。\n·「輪轉之書」：使用時可從中任選1個「輪轉之相」中的SSR命輪獲得。\n·「命途回溯之心」：使用時可從中任選1個「輪轉之相」、往期命輪活動喚醒和當期命輪活動喚醒中的SSR命輪。"
