  LanguageConfig_BonusCardTipsContent_CN = {
    Text = "1、守密人擁有特定喚醒體或命輪（不要求上陣）可以使「紊亂情慾」關卡任務報酬中的「豐穰種核」獲得額外的掉落加成（包括重現），具體加成如下：\n·喚醒體「泰旖絲」：啟靈0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命輪「慈悲的哺育」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命輪「灼熱的吻別」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同喚醒體或命輪的「強欲加成」以疊加的方式結算。"
