  LanguageConfig_CosmeticsRandChestRateText_CN = {
    Text = "<Title:機率說明>\n1、每次使用後有 10% 的機率獲得無形者禮券的「專屬頭像和對戰表情」，90%的機率獲得往期核心課題、相位對弈賽季的限定頭像和對戰表情。\n2、所有專屬頭像和對戰表情均分 10% 機率。具體可查看下文的「專屬頭像和對戰表情清單」。\n3、核心課題的限定頭像和對戰表情將在該期學期課題結束約 1 年後會加入掉落清單。相位對弈賽季獎勵的對戰表情則將在該賽季結束後立即加入掉落清單。\n4、所有往期限定頭像和對戰表情均分 90%的機率。特別的，「無形者的請柬」也視為 1 個往期限定頭像和對戰表情，當掉落清單中沒有其他往期限定頭像和對戰表情時，此時「無形者的請柬」獨佔90%的機率。\n5、當獲得已有的頭像或表情時，將轉換為「無形者的請柬」× 1。收集一定數量的「無形者的請柬」使用，可任選一個「無形者的禮券」中的未獲得的頭像或對戰表情。\n\n<Title:專屬頭像和對戰表情清單>\n1、專屬頭像包括：\n以銀鑰之名：艾爾瓦、以銀鑰之名：戈利亞、以銀鑰之名：尤烏哈希、以銀鑰之名：卡茜亞、以銀鑰之名：訶勒特、以銀鑰之名：德克斯特、以銀鑰之名：茜爾維亞、以銀鑰之名：威廉。\n2、專屬對戰表情包括：\n發瘋彌薩格：尤烏哈希·我要、發瘋彌薩格：布朗·不知道、發瘋彌薩格：希洛·殺殺殺、輕鬆彌薩格：茜爾維亞·喝茶、輕鬆彌薩格：訶勒特·熬夜、輕鬆彌薩格：奧吉爾·敬禮、輕鬆彌薩格：蘿坦·哥倆好、輕鬆彌薩格：拉蒙娜·扶額、輕鬆彌薩格：朵爾·電量不足、相位通訊：守密人·我？、智慧彌薩格：戈利亞·強、智慧彌薩格：雷婭·流淚、智慧彌薩格：諾締拉·誒？、智慧彌薩格：詹金·思索、智慧彌薩格：阿格里帕·暗中觀察、智慧彌薩格：凱刻斯·記仇、小小彌薩格：詹金·吐舌。"
  },
