  LanguageConfig_DailyChallengeAwardIllustrateContent_CN = {
    Text = "1、根據今日通關幻夢深潛的最高難度決定次日獲取的「融蝕之珠」獎勵，各難度對應的獎勵如下：\n·幻夢深潛Ⅰ：融蝕之珠*300\n·幻夢深潛Ⅱ：融蝕之珠*400\n·幻夢深潛Ⅲ：融蝕之珠*500\n·幻夢深潛Ⅳ：融蝕之珠*600\n·幻夢深潛Ⅴ：融蝕之珠*700\n·幻夢深潛Ⅵ：融蝕之珠*800\n·幻夢深潛Ⅶ：融蝕之珠*900\n·幻夢深潛·癲狂：融蝕之珠*900\n2、獎勵將於次日通過結算郵件發送，請守密人記得查收。\n3、如果守密人在參與「幻夢深潛」或「外勤代理」當日同時參與了「相位對弈」，則次日9點結算的融蝕之珠獎勵，將以每日幻夢獎勵和「相位對弈」排行獎勵中更高的融蝕之珠獎勵為准。"
