  },
  LanguageConfig_DailyChallengeEnterButton_CN = {Text = "挑戰"},
  LanguageConfig_DailyChallengeExpAttenuationRulesTipsAlert_CN = {
    Text = "獲得深潛經驗降低"
  },
  LanguageConfig_DailyChallengeExpAttenuationRulesTipsTitle_CN = {
    Text = "規則說明"
  },
  LanguageConfig_DailyChallengeExpAttenuationRulesTips_CN = {
    Text = "·當「守密人等級」或「隊伍平均等級」顯著高於挑戰關卡的推薦等級時，則獲得深潛經驗降低。"
  },
  LanguageConfig_DailyChallengeExpOutAttenuation_CN = {
    Text = "獎勵衰減"
  },
  LanguageConfig_DailyChallengeExpOutBase_CN = {
    Text = "基礎獎勵"
  },
  LanguageConfig_DailyChallengeExpRewardCoefficientLevelTips_CN = {
    Text = "·若「守密人等級」與關卡的推薦等級相近，則挑戰勝利即可完成深潛成就，獲得「深潛經驗」。\n   ·「挑戰征程」：當挑戰難度的「推薦等級」高於 「守密人等級」- 40 級 時，可獲得基礎深潛經驗。\n   ·「超越征程」：當挑戰難度的「推薦等級」高於 「守密人等級」- 20 級 時，可再額外獲得一份基礎深潛經驗。"
  },
  LanguageConfig_DailyChallengeExpRewardTask1_CN = {
    Text = "挑戰征程"
  },
  LanguageConfig_DailyChallengeInstructionsV2_CN = {
    Text = "<Title:【幻夢深潛】>\n·初始造物、關卡造物會在每週一9點(UTC+8)時發生變化。\n·每次挑戰都會隨機進入一個挑戰場景。\n<Title:【深潛經驗】>\n·若「守密人等級」與關卡的推薦等級相近，則挑戰勝利即可完成深潛成就，獲得「深潛經驗」。\n   ·「挑戰征程」：當挑戰難度的「推薦等級」高於 「守密人等級」- 40 級 時，可獲得基礎深潛經驗。\n   ·「超越征程」：當挑戰難度的「推薦等級」高於 「守密人等級」- 20 級 時，可再額外獲得一份基礎深潛經驗。\n<Title:【深潛等級】>\n·當深潛經驗達到一定值時，深潛等級提升。每升一級都可以獲得豐富的獎勵。\n<Title:【賽季更新】>\n·一般情況下，賽季每 28 天重置。\n·調查結束會獲得調查評分，每賽季會記錄本賽季最高的調查評分用作當賽季排行，可重複調查以提高評分。當與其他守密人的調查評分相同時，將會視為同一名次。\n·賽季結束時會結算本賽季排名，並通過郵件發送本賽季排名獎勵。守密人可以通過點擊「排行榜」-「排行獎勵」中查看排行獎勵。\n·每個賽季均會有賽季任務，完成賽季任務即可獲得豐富的獎勵。賽季任務會在賽季結束時重置。\n<Title:【每賽季強化喚醒體】>\n·每賽季的每個界域會有兩名隨機喚醒體在本賽季的幻夢深潛行動中變得躁狂，因此其體質、攻擊力、防禦力提高50%。\n<Title:【調查評分】>\n·調查結束會用當前關卡的難度基礎分跟完成的評分項進行結算，挑戰越高難度時難度基礎分越高。\n·下面是具體評分項。\n1、「時序沙漏」：初始回合為 50，每剩餘 1 回合額外獲得 20 分。\n2、「深淵呼喚」：使用 1 / 2 / 3 / 4 名強化喚醒體時出戰時，獲得 250 / 500 /750 / 1000 分。\n3、「幻境援救」：每使用 1 次應急靈知體，調查評分降低 20% ，多次觸發多次乘算。\n4、「拓夢先驅」：每日首次遊玩 獲得 500 分。"
  },
  LanguageConfig_DailyChallengeInstructions_CN = {
    Text = "<Title:【幻夢深潛】>\n·初始造物、關卡造物會在每週一9點(UTC+8)時發生變化。\n·每次挑戰都會隨機進入一個挑戰場景。\n<Title:【深潛經驗】>\n·若「守密人等級」與關卡的推薦等級相近，則挑戰勝利即可完成深潛成就，獲得「深潛經驗」。\n   ·「挑戰征程」：當挑戰難度的「推薦等級」高於 「守密人等級」- 40 級 時，可獲得基礎深潛經驗。\n   ·「超越征程」：當挑戰難度的「推薦等級」高於 「守密人等級」- 20 級 時，可再額外獲得一份基礎深潛經驗。\n<Title:【深潛等級】>\n·當深潛經驗達到一定值時，深潛等級提升。每升一級都可以獲得豐富的獎勵。\n<Title:【賽季更新】>\n·一般情況下，賽季每 28 天重置。\n·調查結束會獲得調查評分，每賽季會記錄本賽季最高的調查評分用作當賽季排行，可重複調查以提高評分。當與其他守密人的調查評分相同時，將會視為同一名次。\n·賽季結束時會結算本賽季排名，並通過郵件發送本賽季排名獎勵。守密人可以通過點擊「排行榜」-「排行獎勵」中查看排行獎勵。\n·每個賽季均會有賽季任務，完成賽季任務即可獲得豐富的獎勵。賽季任務會在賽季結束時重置。\n<Title:【每賽季強化喚醒體】>\n·每賽季的每個界域會有兩名隨機喚醒體在本賽季的幻夢深潛行動中變得躁狂，因此其體質、攻擊力、防禦力提高50%。\n<Title:【調查評分】>\n·調查結束會用當前關卡的難度基礎分跟完成的評分項進行結算，挑戰越高難度時難度基礎分越高。\n·下面是具體評分項。\n1、「時序沙漏」：初始回合為 50，每剩餘 1 回合額外獲得 20 分。\n2、「深淵呼喚」：使用 1/2 名強化喚醒體時出戰時，獲得 250 / 500 分。\n3、「幻境救援」：每使用 1 次應急靈知體，調查評分降低 20% ，多次觸發多次乘算。\n4、「拓夢先驅」：每日首次遊玩 獲得 500 分。"
  },
