  LanguageConfig_DailyCopyChallengeBtnText_CN = {Text = "挑戰"},
  LanguageConfig_DailyCopyRules_CN = {
    Text = "1、融蝕之墟內通關對應的關卡後可獲得大量喚醒體升格素材、「靈知製劑」和「薔薇金券」！\n2、完成關卡挑戰後解鎖重現，重現可以立即獲得該關卡的任務報酬。每次重現需消耗等同於進行調查所需的「靈啡肽」。\n3、在調查等級達到 20 級後解鎖技能素材關卡。\n4、若三星通關高難度關卡，則較低難度的關卡挑戰進度會自動標記為三星通關。"
