  LanguageConfig_DiamondDonateDesc_CN = {
    Text = "您捐獻的每滴源液都彌足珍貴，它們會投入融蝕研究和校舍建設中，化作彌薩格的一部分，與各位一同奔赴那個不被遺忘的未來。\n願銀鑰指引我們。"
