  LanguageConfig_DiamondDonateTipContent_CN = {
    Text = "<Title:捐獻規則>\n·透過「源液捐獻」消耗的「源液」都會計入累計捐獻值。\n·此外、在「喚醒」中「銀芯」不足時直接捐獻的源液也會計入。\n<Title:獎勵規則>\n·每捐獻 1 滴「源液」對應獲得 1 點貢獻值。\n·貢獻值每達到 2500 可獲得 1 份特別回饋。\n·每 20 份回饋為一輪循環。\n·每輪循環總計回饋包括：「精粹原初靈核」×1、「原初靈核」×3、「賢者之石」×6、「追憶羽筆」×800、「無形者的禮券」×100、「千面印章」×5000、「薔薇金券」×50000000。"
