  LanguageConfig_EnergyMonthCardRuleContent_CN = {
    Text = "【鞘內補給介紹】\n每次購買鞘內補給、可立即獲得「銀芯」× 680 與為期 30 天的鞘內補給生效時間。\n鞘內補給生效時間內、每日可從郵箱中領取「靈啡肽」× 300 和「追憶羽筆」× 30、每日9點重置【UTC+8】。\n \n【注意事項】\n鞘內補給剩餘生效時間≤180天時續購、總生效時間才會延長。\n當鞘內補給剩餘生效時間＞180天時不可再進行購買。\n如因特殊原因導致重複購買、總生效時間將無法進行累加、並將直接返還「銀芯」× 680。\n玩家在鞘內補給生效期間未領取的「靈啡肽」和「追憶羽筆」、將不會返還。"
