  LanguageConfig_ExchangeShopRules_CN = {
    Text = "<Title:兌換商店>\n·守密人可以在各個兌換商店通過消耗一定的對應貨幣兌換商品。\n·當守密人調查等級提升時，兌換商店會隨之升級並解鎖新內容。\n·兌換商店內的商品每隔一定的時間會自動刷新庫存。\n\n<Title:金券兌換>\n·守密人可以在首次通關主線調查事件或通過「融蝕之墟：金券搜查」、「派遣獎勵」、「課題獎勵」與限時玩法活動獎勵來獲得「薔薇金券」。\n\n<Title:沉澱兌換>\n·守密人可以通過喚醒來獲得「根源沉澱」。\n\n<Title:調查兌換>\n·守密人可以在主線調查事件獲得三星關卡星級或通過「超驗存在」來獲得「調查徽章」。\n\n<Title:無光兌換>\n·守密人可以通過「無光之境」或通過「融災禁區」來獲得「黑色供物」。\n\n<Title:融珠兌換>\n·守密人可以通過「常訓任務：每週試煉」來獲得「融蝕之珠」。"
