  LanguageConfig_FriendInvitationRule_CN = {
    Text = "<Title:邀請活動>\n1.守密人可以透過分享邀請碼來邀請新的守密人加入彌撒格校園、共赴冒險之旅。\n2.受邀的守密人完成任務後、您可以領取任務獎勵獲得「銀鑰輝光」、當「銀鑰輝光」達到一定數量後、可以領取豐富的獎勵！\n3.守密人等級達到5/10/15/20級後可以分別獲得20/20/20/40「銀鑰輝光」。\n4.每位守密人最多可以透過50位邀請的守密人獲取任務獎勵、超出數量的部分不再提供任務獎勵。\n5.邀請的守密人在調查等級達到5級後才會被計入已邀請人數。\n<Title:綁定邀請>\n1.守密人可以填寫邀請碼來跟邀請的玩家進行綁定、並立即獲得「銀芯」× 300的獎勵！\n2.每位守密人只能在初到彌撒格的前7天內輸入邀請碼、超時後「綁定邀請」的入口將會關閉。"
  },
