  LanguageConfig_LargeSubplotResonanceRules_CN = {
    Text = "1、「特遣紀錄」的部分調查事件有專屬共鳴，可以使用共鳴升級材料激活共鳴效果，共鳴將在調查時提供強力的協助。\n2、在喚醒體限時活動期間，完成指定任務可以獲得共鳴升級材料。活動結束後，可通過消耗「薔薇金券」× 5000 額外兌換 1 個共鳴升級材料。\n3、地圖內會出現共鳴節點，移動至共鳴節點上將在本次探索獲得共鳴效果。"
  },
  LanguageConfig_LargeSubplotTipsText_CN = {
