  LanguageConfig_LotteryPhoneticDialogue66_CN = {
    Text = "臨時文本"
  },
  LanguageConfig_LotteryPhoneticDialogue6_CN = {
    Text = "哦，運氣不錯嘛。不像隔壁大約翰，我的東西都是講究實際效果的。希望它能對你有用。"
  },
  LanguageConfig_LotteryPhoneticDialogue7_CN = {
