  LanguageConfig_LotteryPhoneticDialogue8_CN = {
    Text = "我能感受到你的不滿足……那就期盼我、索求我吧。"
  },
  LanguageConfig_LotteryPhoneticDialogue9_CN = {
    Text = "靜靜聆聽吧。這清脆的聲響，便是神國對你的回應。"
