  LanguageConfig_LotteryRuleContent_CN = {
    Text = "1、「柯蕾特的花房」共有三個花圃，開啟時間如下：\n·「鳶尾花圃」： 7 月 15 日 9 時開啟。\n·「桔梗花圃」： 7 月 17 日 9 時開啟。\n·「薔薇花圃」： 7 月 19 日 9 時開啟。\n2、每次交換將消耗 1000「惆悵的詩文」/「遺憾的詩文」/「歡欣的詩文」，隨機獲得花圃中的五個物品獎勵。\n3、每個花圃的物品獎勵分為「特殊物品」和「普通物品」兩種，重置時可以使特殊物品獎勵的剩餘數量重置至上限，具體規則為：\n（1）前2次重置：當「特殊物品」無剩餘數量後，守密人可以選擇重置，重置後會將「特殊物品」和「普通物品」的剩餘數量重置至上限；也可以選擇繼續交換，當「普通物品」也無剩餘數量後，須進行重置才可以繼續交換。\n（2）第3次開始重置：當「普通物品」無剩餘數量後才可以進行重置，重置會將「普通物品」的剩餘數量重置至上限，「特殊物品」不再重置。\n4、8 月 5 日 9：00（GMT+8）後，剩餘未交換的「詩文」將按照每200個兌換「薔薇金券*5000」的比例進行回收，請守密人注意查收郵件。"
  },
