  LanguageConfig_Monster_B0001_2_CN = {
    Text = "對不起…"
  },
  LanguageConfig_Monster_B0001_3_CN = {
    Text = "當心！本回合未被打出的卡牌都將化為石頭…"
  },
  LanguageConfig_Monster_B0002_1_CN = {
    Text = "好餓，喬治好餓……"
  },
  LanguageConfig_Monster_B0002_2_CN = {
    Text = "不要拋棄喬治，不要拋棄我們……！"
