  LanguageConfig_Monster_B0005_7_CN = {
    Text = "「褻瀆之徒…降以極刑！」"
  },
  LanguageConfig_Monster_B0005_CN = {
    Text = "「瀆神者…我將以代行者之名，降下神罰！」"
  },
  LanguageConfig_Monster_B0005_Tips_1_CN = {
    Text = "曾名為「彌利亞姆」的異怪，正在祈禱神之注視……"
  },
  LanguageConfig_Monster_B0007_SideDia1_CN = {
    Text = "母樹吞噬了大量亞蘭血肉……"
