  },
  LanguageConfig_Monster_B05EX_SideDia30_CN = {
    Text = "終末，即將降臨…！"
  },
  LanguageConfig_Monster_B05EX_SideDia31_CN = {
    Text = "親眼見證終末吧！"
  },
  LanguageConfig_Monster_B05EX_SideDia32_CN = {
    Text = "這裡可是我的實驗室…"
