  LanguageConfig_Monster_B05EX_SideDia3_CN = {
    Text = "每打出 3 張卡牌後會凍結 1 張指令卡，小心行事！"
  },
  LanguageConfig_Monster_B05EX_SideDia4_CN = {
    Text = "殘餘的凍結卡牌本回合會被全部粉碎，並化為敵人的傷害…當心！"
  },
  LanguageConfig_Monster_B05EX_SideDia5_CN = {
