  },
  LanguageConfig_Monster_C0603_Title_CN = {
    Text = "當心！釋放狂氣爆發會使敵人獲得「孕育」狀態，增強敵人的力量，達到 5 層還會釋放強力技能！"
  },
  LanguageConfig_Monster_C06_Tips_1_CN = {
