  LanguageConfig_Monster_C703_SideDia1_CN = {
    Text = "&…%…&融為*（）一體&……%"
  },
  LanguageConfig_Monster_C703_SideDia2_CN = {
    Text = "當心！抽到症狀或狀態卡時，「努比亞」們會獲得臨時力量！"
  },
  LanguageConfig_Monster_C704BOSS_SideDia1_CN = {
    Text = "列陣！據守！"
