  },
  LanguageConfig_Monster_C706BOSS_SideDia1_CN = {
    Text = "以漫天黃沙…為你送葬……"
  },
  LanguageConfig_Monster_C706BOSS_SideDia2_CN = {
    Text = "當心！敵人將號令滿天的黃沙，吞噬所有喚醒體的狂氣！"
  },
  LanguageConfig_Monster_Castor_01_CN = {
    Text = "無論前方阻擋我們的是什麼，我都會帶他再次逃出去。"
