  },
  LanguageConfig_Monster_Chapter8_10_CN = {
    Text = "小心！敵人即將造成穿刺傷害和高額脆弱，護盾手段會受到影響！"
  },
  LanguageConfig_Monster_Chapter8_11_CN = {
