  LanguageConfig_MonthCardRuleText_CN = {
    Text = "<Title:【月相觀測介紹】>\n·每次購買月相觀測、可立即獲得「銀芯」× 300 和為期 30 天的月相觀測許可。\n·月相觀測生效時間內、每日登入可領取「銀芯」× 200。（每日9點更新【UTC+8】）\n\n\n<Title:【注意事項】>\n·月相觀測剩餘生效時間≤150天內續購、可延長生效時間。\n·守密人在月相觀測生效期間如因未登入而未領取的「銀芯」不會返還。"
