  },
  LanguageConfig_PVPGoodBtnUnClickableStateTips_CN = {
    Text = "已經點贊過對手啦"
  },
  LanguageConfig_PVPInstructions_CN = {
    Text = "<Title:【相位對弈】>\n· 相位對弈模式是《忘卻前夜》附贈玩法，每個賽季遊戲每張卡牌和整體遊戲玩法都可能會大幅度重做變化，來換取更平衡更有趣的遊戲環境，因此請謹慎為解鎖相位對弈的遊戲內容而投入資源。\n<Title:【匹配相關】>\n· 相位對弈是兩人對抗遊戲，需要透過匹配功能等待一段時間以尋找對手，匹配功能會優先尋找旗鼓相當的對手與你進行對抗。\n·同步匹配：守密人可以勾選「預組模式」與「輪選模式」同時對多模式進行匹配，可以有效縮短匹配到對手的等待時間。\n·精準匹配：開啟設定會尋找更勢均力敵的對手，但這會延長匹配到對手的等待時間。關閉設定會縮短匹配到對手的等待時間，但對手相對不那麼勢均力敵。\n·模擬對手：開啟設定將允許匹配時看情況分配模擬對手，這會縮短匹配到對手的等待時間。關閉設定將僅允許匹配時分配真人對手，這會延長匹配到對手的等待時間。\n<Title:【積分排名】>\n·分數規則：初始積分為 0 分，守密人可透過匹配對戰獲得積分。\n·分數變化：當雙方分數一致時，勝利方將獲得 5％ 總積分的積分，失敗方將失去等值積分。\n·新手保護：當積分低於 1500 時，勝利時將獲得更多的分數，失敗時將失去更少的分數。\n·強敵挑戰：當戰勝強敵時獲得更多的分數，敗於強敵時將失去更少的分數。戰勝弱敵時獲得更少的分數。\n·分數獨立：「預組模式」與「輪選模式」各自擁有獨立的積分，但二者一致使用上述積分規則。\n<Title:【賽季更新】>\n·賽季重置：一般情況下，賽季每 28 天重置。重置後，所有人的積分超過 3000 的部分將會減半。\n·賽季排行：「預組模式」與「輪選模式」各自擁有獨立的賽季和賽季排行，賽季排行獎勵將會在每次賽季結束時進行結算。\n·排行條件：當前賽季內參與一場即可進入對應模式的賽季排行，並以賽季內的歷史最高分作為排名依據。當前賽季內獲勝一場即可在賽季結束時根據當前賽季排行結算獎勵。\n·賽季任務：「預組模式」與「輪選模式」均會有賽季任務，完成賽季任務可以獲得豐富的獎勵。賽季任務會在每次賽季更新時重置。\n<Title:【預組模式】>\n· 「預組模式」是相位對弈的基礎模式，使用預先準備的編隊與對手進行對抗，在匹配前需要選擇自己的編隊與未知編隊的對手進行對抗。\n<Title:【輪選模式】>\n·「輪選模式」是相位對弈的進階模式，無需預組隊伍便可進行匹配，在開始戰鬥前雙方需要在一個擁有喚醒體、命輪、鑰令的卡池中輪流選取，以此構建自己的編隊在後續與對方進行對戰。\n· 每場對局中系統會隨機選取一個造物，在對戰中生效。"
  },
  LanguageConfig_PVPMatchDefeat_CN = {
    Text = "比賽失敗"
  },
  LanguageConfig_PVPMatchVictory_CN = {
    Text = "比賽勝利"
  },
  LanguageConfig_PVPOpeningVoiceUnlockDesc_CN = {
    Text = "在相位對弈中觸發該對話後解鎖"
  },
  LanguageConfig_PVPRankRewardCountdown_CN = {
    Text = "當前賽季剩餘{s1}天{s2}小時"
  },
  LanguageConfig_PVPRankingRuleDesc_CN = {
    Text = "<Title:【積分排行】>\n·【預組模式】與【輪選模式】各自擁有獨立的賽季和賽季排行，賽季排行獎勵將會在每次賽季結束時進行結算。\n·當前賽季內參與一場即可進入對應模式的賽季排行，並以賽季內的歷史最高分作為排名依據。當前賽季內獲勝一場即可在賽季結束時根據當前賽季排行結算獎勵。\n<Title:【排名比例】>\n·對弈頭銜按參與排行的積分排名，比例如下：\n     ·相位傳奇：前2％\n     ·相位支配者：2％~10％\n     ·對弈大師：10％~25％\n     ·相位精英：25％~50％\n     ·對弈學徒：50％~75％\n     ·相位新手：75％後\n·當出現與其他守密人相同積分的情況時，將按照進入排行的先後進行排序，但對弈頭銜和獎勵仍以此分的最高排名為準。"
  },
