  LanguageConfig_PasswordBattleQueueButton_CN = {Text = "排隊中"},
  LanguageConfig_PasswordBattleRuleTips_CN = {
    Text = "·密碼對戰：在創建對戰後，可以通過在 社交媒體 或 通訊軟件中發佈 <color=#5EF2FF>相位值</color> 對群體發起邀請，其他守密人可以通過輸入 <color=#5EF2FF>相位值</color> 加入你的對戰，由於同時只能與一個人發起對戰，因此對戰名額先到先得，成功開啟對戰後其他應邀的守密人將被拒絕。\n·拒絕對戰：若遇到不想與其對戰的守密人創建者也可拒絕與其對戰，拒絕過多會出現拉黑提示，可通過拉黑操作阻止其加入你的對戰，直至解除拉黑。"
