  LanguageConfig_PermanentActivityRuleContent_CN = {
    Text = "<Title:記憶迴廊>\n·帶有「記憶迴廊」標記的活動，在活動時間結束後將被收錄到「記憶迴廊」中，可繼續在「記憶迴廊」中體驗相應的玩法和劇情。\n<Title:收錄規則>\n·帶有「記憶迴廊」標記的活動會有豐富的限時獎勵，在活動時間結束後限時獎勵將無法再領取，請各位守秘人及時領取限時獎勵。\n·活動被收錄到「記憶迴廊」後，會自動保留此前的進度，各位守秘人可繼續體驗。"
