  LanguageConfig_PlayerExpRuleContent_CN = {
    Text = "<Title:至高禮讚>\n1、在「智識贈禮」活動中，完成每個任務均可獲得一個「至高禮讚」效果，使守密人經驗獲得加速，最高可達 100%。多個「至高禮讚」效果同時存在時，取最高的加速效果。\n2、解鎖或獲得更高級的「至高禮讚」效果時，會按照加速比例和當前可被加速的守密人經驗總量，立即獲得額外的守密人經驗。\n3、解鎖「至高禮讚」後，守密人每次獲得守密人經驗時，都將獲得對應加速比例的額外守密人經驗。\n4、請注意，「至高禮讚」帶來的額外守密人經驗不會計入可被加速的守密人經驗總量。\n5、當前可被加速的守密人經驗總量：{s1}。\n6、加速已累計獲得額外守密人經驗：{s2}（{s3}%）。"
