  LanguageConfig_RailWayResonanceRuleContent_CN = {
    Text = "1、在「疾馳的歡愉專列」有更豐富的共鳴強化、以便在挑戰中為守密人們提供強力的協助。\n2、在「沿途留影」中可以獲得共鳴升級材料、消耗材料可以啟用共鳴效果。\n3、每個階段都會有調查行動共鳴事件、進入調查行動共鳴事件後將獲得對應章節的強力共鳴效果、該共鳴效果會持續至整場調查結束。\n4、在「小」N「的協助」中獲得的共鳴效果將會從調查開始持續至調查結束。"
  },
  LanguageConfig_RailWayRulesContentV2_CN = {
    Text = "<Title:玩法簡介>\n1、「疾馳的歡愉專列」是採用「星辰篇」規則的連續挑戰模式。守密人將在多變的隨機遭遇中連續挑戰多個調查行動中出現過的最終首領！\n2、玩法中造物持有上限最高可提升至 36 個。\n3、挑戰過程中可同時擁有並強化 3 種調查行動中的強大「共鳴」效果。\n4、每使用 1 次應急靈知體，會減少 20% 本次挑戰獲取的「貴賓積分」。\n5、支持中途退出並保留進度，但隊伍狀態不會隨外部養成變化同步更新。進度至多保留至上一次挑戰的 7 天後，若保留期間沒有繼續挑戰則視為放棄挑戰，進度不再保留。\n\n<Title:等級補償>\n參與「列車啟程」會獲得等級補償，具體規則如下：\n  ·調查隊伍中，等級不足 60 級的喚醒體在本次挑戰中將會補償至 60 級。\n  ·調查隊伍中，技能等級不足 5 級的喚醒體在本次挑戰中將會補償至 5 級。\n  ·調查隊伍中，「瘋狂預兆」不足 6 級的喚醒體在本次挑戰中將會補償至 6 級。\n  ·調查隊伍中，「靈塑適性」不足 5 級的喚醒體在本次挑戰中將會補償至 5 級。\n  ·若守密人等級不足60級，在本次挑戰中將會補償至60級。\n\n<Title:關卡階段>\n1、單次挑戰總計分為三個階段，每個階段的主題敵人與共鳴效果將在對應範圍內隨機生成：\n  ·第一階段： 對應「忘卻篇」第一至四章內容。\n  ·第二階段： 對應「忘卻篇」第五至八章內容。\n  ·第三階段： 對應「星辰篇」第一至四章內容。\n ·在癲狂難度下，完成第三階段挑戰後將額外挑戰第四階段最終首領「塔薇」。\n2、擊敗階段首領後，可從隨機 3 個「時之靈擺」中擇一獲取。\n\n<Title:難度與初始造物>\n本次挑戰共設三個難度，各難度有不同的關卡獎勵和初始造物，各位守密人可以在選擇挑戰難度前了解詳細信息。\n\n<Title:關卡獎勵>\n1、通過擊敗各難度中的精英與首領可獲取「貴賓積分」，「貴賓積分」用於提升「雅室規格」等級以獲取獎勵。\n  ·第一階段：擊敗精英/首領獲得「貴賓積分」×25/75 \n  ·第二階段：擊敗精英/首領獲得「貴賓積分」×50/150 \n  ·第三階段：擊敗精英/首領獲得「貴賓積分」×75/225 \n2、挑戰的難度越高，將會獲得越多的「貴賓積分」。\n  ·【困難難度】：完成三個階段獲得的「貴賓積分」提高 150% \n\n  ·【癲狂難度】：完成三個階段獲得的「貴賓積分」提高 400%\n ·擊敗最終首領「塔薇」後，可額外獲得「貴賓積分」× 1500。\n\n<Title:賽季更新>\n1、「貴賓名錄」會記錄挑戰表現優異的守密人，每個賽季期間挑戰 1 次，並且成功獲得「貴賓積分」的守密人即可進入「貴賓名錄」。\n2、「貴賓名錄」的賽季排名會以單次挑戰獲得最多的「貴賓積分」和所用最少的「回合數」為依據，可重複挑戰以提高排名。\n3、賽季結束後，會通過郵件結算本賽季「貴賓名錄」的排名獎勵。\n4、每個賽季均會有賽季任務，完成賽季任務即可獲得豐富的獎勵。賽季任務會在每次賽季更新時重置。\n5、賽季切換時，尚在戰鬥中的關卡在完成挑戰後可以直接完成最新的賽季任務，但無法進入「貴賓名錄」。"
  },
  LanguageConfig_RailWayRulesContent_CN = {
    Text = "<Title:玩法簡介>\n1、「疾馳的歡愉專列」是採用「星辰篇」規則的連續挑戰模式。守密人將在多變的隨機遭遇中連續挑戰多個調查行動中出現過的最終首領！\n2、玩法中造物持有上限最高可提升至 36 個。\n3、挑戰過程中可同時擁有並強化 3 種調查行動中的強大「共鳴」效果。\n4、每使用 1 次應急靈知體，會減少 20% 本次挑戰獲取的「貴賓積分」。\n5、支持中途退出並保留進度，但隊伍狀態不會隨外部養成變化同步更新。進度至多保留至上一次挑戰的 7 天後，若保留期間沒有繼續挑戰則視為放棄挑戰，進度不再保留。\n\n<Title:等級補償>\n參與「列車啟程」會獲得等級補償，具體規則如下：\n  ·調查隊伍中，等級不足 60 級的喚醒體在本次挑戰中將會補償至 60 級。\n  ·調查隊伍中，技能等級不足 5 級的喚醒體在本次挑戰中將會補償至 5 級。\n  ·調查隊伍中，「瘋狂預兆」不足 6 級的喚醒體在本次挑戰中將會補償至 6 級。\n  ·調查隊伍中，「靈塑適性」不足 5 級的喚醒體在本次挑戰中將會補償至 5 級。\n  ·若守密人等級不足60級，在本次挑戰中將會補償至60級。\n\n<Title:關卡階段>\n1、單次挑戰總計分為三個階段，每個階段的主題敵人與共鳴效果將在對應範圍內隨機生成：\n  ·第一階段： 對應「忘卻篇」第一至四章內容。\n  ·第二階段： 對應「忘卻篇」第五至八章內容。\n  ·第三階段： 對應「星辰篇」第一至四章內容。\n2、擊敗階段首領後，可從隨機 3 個「時之靈擺」中擇一獲取。\n\n<Title:難度與初始造物>\n本次挑戰共設三個難度，各難度有不同的關卡獎勵和初始造物，各位守密人可以在選擇挑戰難度前了解詳細信息。\n\n<Title:關卡獎勵>\n1、通過擊敗各難度中的精英與首領可獲取「貴賓積分」，「貴賓積分」用於提升「雅室規格」等級以獲取獎勵。\n  ·第一階段：戰勝精英/首領獲得「貴賓積分」×25/75 \n  ·第二階段：戰勝精英/首領獲得「貴賓積分」×50/150 \n  ·第三階段：戰勝精英/首領獲得「貴賓積分」×75/225 \n2、挑戰的難度越高，將會獲得越多的「貴賓積分」。\n  ·【困難難度】：完成三個階段獲得的「貴賓積分」提高 150%\n  ·【癲狂難度】：完成三個階段獲得的「貴賓積分」提高 400%\n\n<Title:賽季更新>\n1、「貴賓名錄」會記錄挑戰表現優異的守密人，每個賽季期間挑戰 1 次，並且成功獲得「貴賓積分」的守密人即可進入「貴賓名錄」。\n2、「貴賓名錄」的賽季排名會以單次挑戰獲得最多的「貴賓積分」和所用最少的「回合數」為依據，可重複挑戰以提高排名。\n3、賽季結束後，會通過郵件結算本賽季「貴賓名錄」的排名獎勵。\n4、每個賽季均會有賽季任務，完成賽季任務即可獲得豐富的獎勵。賽季任務會在每次賽季更新時重置。\n5、賽季切換時，尚在戰鬥中的關卡在完成挑戰後可以直接完成最新的賽季任務，但無法進入最新一期「貴賓名錄」。"
  },
