  LanguageConfig_RailWayStageDifficultyBuffContent1_CN = {
    Text = "<Title:關卡獎勵>\n第一階段：擊敗精英/首領獲得「貴賓積分」×25/75 \n第二階段：擊敗精英/首領獲得「貴賓積分」×50/150 \n第三階段：擊敗精英/首領獲得「貴賓積分」×75/225 \n<Title:初始造物>\n調查開始時獲得造物「小」N「的完整相機」\n·<OrangeQuality:黃金調和>：「算力調和」帶來的算力提升效果最大為 1 點、每擁有 1% 傷害強效則使得靈識研究深度效果提高 1%。\n·<RedQuality:長途倦意>：戰鬥中所有生命回覆效果降低 50%。"
