    Text = "<Title:關卡獎勵>\n挑戰的難度越高、將會獲得越多的「貴賓積分」。完成三個階段獲得的「貴賓積分」提高 150%\n<Title:初始造物>\n調查開始時獲得造物「小」N「的破舊相機」\n·<OrangeQuality:黃金調和>：「算力調和」帶來的算力提高效果最大為 1 點、每擁有 1% 傷害強效則使得靈識研究深度效果提高 1%。\n·<OrangeQuality:維度贈禮>：探索開始時、隨機獲得 1 個維度影像造物、手牌上限提高 1 。\n·<RedQuality:長途倦意>：戰鬥中所有生命回覆效果降低 50%。\n·<RedQuality:暈眩徵兆>：戰鬥開始時、所有喚醒體當前狂氣與銀鑰能量降低 50%。"
