  },
  LanguageConfig_Resonance_Group_Desc_5_CN = {
    Text = "於關卡「沉溺之徒」及之後關卡的節點【代行之儀】處，可獲得「神國腕肢」效果——回合結束後對前排敵方造成自身隊伍 10% 最大生命的傷害。\n可將一張「代行者的裁決」加入牌庫——0算力消耗，打出後失去 10% 當前生命，使「神國腕肢」對後排敵方造成 3 倍傷害，若在首領戰中則造成 10 倍傷害。消耗。"
  },
  LanguageConfig_Resonance_Group_Desc_6_CN = {
    Text = "於「純白之帆」處，將一張「烏托邦帷幕」加入牌庫。1 算力消耗，查看 3 個與當前攜帶不同的鑰令，選擇 1 個立即釋放，不會觸發鑰令冷卻。首領戰中可額外使用 1 次。消耗。"
  },
  LanguageConfig_Resonance_Group_Desc_7_CN = {
    Text = "探索起點附近，會遭遇特殊的共鳴事件——【孕育之母】，選擇一張指令卡，使其獲得特殊的【孕育】刻印，但也使你獲得 3 張隨機症狀卡。\n【孕育】刻印：使卡牌獲得保留，回合結束時若在手中，獲得一張附加保留和消耗的原始複製。"
  },
  LanguageConfig_Resonance_Group_Desc_8_CN = {
    Text = "探索起點附近、會遭遇特殊的共鳴事件——【入學儀式】、將【極夜微光】加入牌庫。\n【極夜微光】：選擇抽牌堆或棄牌堆的 1 張指令卡置入手中、並使其算力消耗變為 0。使用 1 次後消耗。"
  },
  LanguageConfig_Resonance_Group_Desc_9_CN = {
