  },
  LanguageConfig_Resonance_Group_Desc_D05EX_CN = {
    Text = "獲得初始造物「科考團」：初始擁有 30 科考團人數。戰鬥開始時，將 5 張「猜疑」置入牌庫中。「猜疑」：打出後將選擇消耗不同的科考團人數，獲得不同效果。\n\n在探索的過程中，將不斷的面臨「猜疑」的抉擇，科考團人員的損失，觸發聯絡處後，還有機會獲得救援，最後安全撤離時，根據剩餘科考團人數獲得「救難勳章」，撤離人數越多「救難勳章」越強大。"
  },
  LanguageConfig_Resonance_Group_Desc_Horla_CN = {
