  LanguageConfig_ReturnEventRewardText_CN = {
    Text = "與融蝕對抗的使命是一條通向未知的不歸路，路上遍佈陷阱與危機。\n而「拯救世界」又是一個太重要，也太容易讓人迷失的課題。在彌薩格大學的歷史上，有不少年輕調查員受到使命感的蠱惑，失去理智地燃燒了自己。\n因此你能做出休息一段時間的決定，我們都很慶倖。我們承受不起又一次失去守密人的損失。\n寒暄到此為止，為了能讓你迅速回到調查狀態，我為你擬定了一套重啟訓練方案。照著做，拿著結果回來找我，我自有獎勵。\n順便，拉蒙娜為你準備了一些「小禮物」。她挺想你的。"
  },
