  LanguageConfig_RootSedimentShopRules_CN = {
    Text = "1、守密人可以通過消耗一定的「根源沉澱」兌換商品。\n2、當守密人調查等級提升時，沉澱兌換商店會隨之升級並解鎖新內容。\n3、沉澱兌換商店內的商品每隔一定的時間會自動刷新庫存。\n4、守密人可以通過喚醒來獲得「根源沉澱」。"
