  },
  LanguageConfig_SchoolTowerRuleTxt_CN = {
    Text = "<Title:無光之境>\n·無光之境，是一系列難度較高的關卡。通關關卡可以領取豐厚獎勵。此外，達成累計的關卡評分星級還可以獲取額外獎勵。\n\n<Title:調查要求>\n·無光之境的關卡可能會要求使用指定界域和數量的喚醒體進行調查，守密人可以在關卡詳情和隊伍配置介面中查看。\n\n<Title:初始造物>\n·無光之境的關卡會存在獨特的造物，該造物僅在當前關卡生效，合理利用造物效果將會使調查事半功倍。"
  },
  LanguageConfig_SchoolTowerTeamBuildFobiddenTips_CN = {
    Text = "當前選擇不滿足隊伍要求"
  },
  LanguageConfig_School_Activate_CN = {Text = "已啟動"},
  LanguageConfig_School_Blood_Content_String_CN = {
    Text = "·回合開始時<CardKeyWord:胚胎融合> +20（隨損失生命提升，最高 40），達到上限時將 1 張<CardKeyWord:「胚胎」>置入手牌。\n·血肉界域的「狂氣爆發」會消耗<CardKeyWord:「胚胎」>觸發<CardKeyWord:吞噬>效果，每回合首次吞噬後會獲得最大生命 2％ 的護盾和 1％ 的臨時力量。（隨損失生命提高，最大為 2 倍）"
  },
  LanguageConfig_School_Blood_Title_String_CN = {
    Text = "猩紅獻祭"
  },
  LanguageConfig_School_Chaos_Content_String_CN = {
    Text = "·混沌界域喚醒體可以突破界域限制與其他界域喚醒體編隊。\n·任意隊伍中如果存在混沌喚醒體，可以額外獲得 100% 死亡抵抗。\n·回合結束和釋放「狂氣爆發」後，<CardKeyWord:銀鑰能量> +50。"
  },
  LanguageConfig_School_Chaos_Title_String_CN = {
    Text = "宇宙萬象"
  },
  LanguageConfig_School_Dimension_Content_String_CN = {
    Text = "·每回合打出的第 1 張指令卡的臨時複製會進入<CardKeyWord:超維空間>並觸發其躍遷效果。\n·當超維空間達到上限時，獲得 1 個額外的超維回合，該回合不再通常抽牌，而是將超維空間的卡牌加入手牌。超維回合能觸發所有躍遷效果。"
  },
  LanguageConfig_School_Dimension_Title_String_CN = {
    Text = "維度躍遷"
  },
  LanguageConfig_School_Ocean_Content_String_CN = {
    Text = "·戰鬥開始時生成 1 條觸腕，觸腕在回合結束時攻擊前排敵人。\n·每釋放 1 次狂氣爆發，在回合結束時驅使 1 條觸腕攻擊。\n·每獲得 3 點力量提供 1 點觸腕傷害，力量每下降 3 點使觸腕傷害降低 1 點。"
  },
