  LanguageConfig_StoryLineTask_String_Available_CN = {Text = "領取"},
  LanguageConfig_StoryLineTask_String_Received_CN = {Text = "已領取"},
  LanguageConfig_StoryLine_EffectTip_CN = {
    Text = "在此處可以查看地形效果以及怪物資訊"
  },
  LanguageConfig_StoryLine_LockAdvance_CN = {
    Text = "{s1}達到{s2}解鎖{s3}"
  },
  LanguageConfig_StoryRole_Unlock_CN = {
    Text = "該劇情線尚未解鎖，無法進入。"
  },
  LanguageConfig_StorylineGuide_10_CN = {
    Text = "當然、混亂是一切的結局。可總有人不願放棄掙扎、不是嗎？"
  },
  LanguageConfig_StorylineGuide_11_CN = {
    Text = "不可直視頭頂的寰宇。不可直視內心的深淵。"
  },
  LanguageConfig_StorylineGuide_12_CN = {
    Text = "進食、是這個世界唯一的美德。"
  },
  LanguageConfig_StorylineGuide_13_CN = {
    Text = "無垠的幻夢裡沒有答案。這場夢境、到了該甦醒的時候了。"
  },
  LanguageConfig_StorylineGuide_14_CN = {
    Text = "命運的舞台之上、我們將扮演的角色、從來無從選擇。"
  },
  LanguageConfig_StorylineGuide_15_CN = {
    Text = "旅人啊，請悄聲步入雪夜。於無願的尖峰，見證大夢的終結。"
  },
  LanguageConfig_StorylineGuide_16_CN = {
    Text = "臨時文本"
  },
  LanguageConfig_StorylineGuide_17_CN = {
    Text = "臨時文本"
  },
  LanguageConfig_StorylineGuide_18_CN = {
    Text = "臨時文本"
  },
  LanguageConfig_StorylineGuide_19_CN = {
    Text = "臨時文本"
  },
  LanguageConfig_StorylineGuide_1_CN = {
    Text = "踏入倫蒂尼恩危險的夜霧吧、守密人。屬於你的路、於此開始。"
  },
  LanguageConfig_StorylineGuide_20_CN = {
    Text = "臨時文本"
  },
  LanguageConfig_StorylineGuide_2_CN = {
    Text = "藝術家、瘋子、苦行者、痴愚之人……這座城市是屬於你的展館、蠟像們站在故事開場的地方、渴盼著你的光臨。"
  },
  LanguageConfig_StorylineGuide_3_CN = {
    Text = "拉伊的風雪厭棄殺戮、她等待著你、只為一場交易。她將帶給你、你無比渴求的秘密。她的價格永遠殘忍、永遠合理。"
  },
  LanguageConfig_StorylineGuide_4_CN = {
    Text = "回憶吧、為回憶而戰、為回憶而死。回憶是我們的福音書、我們的墓誌銘。除了回憶、我們一無所有。"
  },
  LanguageConfig_StorylineGuide_5_CN = {
    Text = "在群星墜落以前、我們面向海洋祈禱：願平靜的濤聲護我們入夢、願我們重回故土的懷抱、長夢不醒。"
  },
  LanguageConfig_StorylineGuide_6_CN = {
    Text = "吟詠吧——那古老的王、已重新看見祂的王座。神聖的諭令、將為每一位虔誠的子民、帶來神的國度。"
  },
  LanguageConfig_StorylineGuide_7_CN = {
    Text = "聆聽、祈禱、呼喚、繁衍、服從最高貴的理想與最卑微的慾望。以母親的名義、祂得以於混沌與恐懼中長存。"
  },
  LanguageConfig_StorylineGuide_8_CN = {
    Text = "長明的燈已燃起、那幽暗的光、將為你照亮通往終途的路。"
  },
  LanguageConfig_StorylineGuide_9_CN = {
    Text = "告訴祂、你的回答。"
  },
  LanguageConfig_StrongerTitle_CN = {
    Text = "通過「幕間演習」獲取素材，強化你的喚醒體吧！"
  },
  LanguageConfig_StrongerWayTitle_CN = {
    Text = "如何變強"
  },
  LanguageConfig_StrongerWay_CN = {
    Text = "·「調查行動」1-2·普通解鎖：「融蝕之墟」，可以獲得大量喚醒體養成素材。\n·「調查行動」3-10·普通解鎖：「超驗存在」，可以獲得大量喚醒體技能升級素材。\n·「調查等級」15級解鎖：「第二命輪」，可以裝備第二命輪獲得強大戰力。\n·「調查等級」25級解鎖：「禁忌纂錄」，可以獲得大量密契，增強喚醒體能力。"
