  LanguageConfig_SummonSelectAwakePanelDesc_CN = {
    Text = "1、循序命理：守密人可從本期循序命理喚醒活動可選的喚醒體清單中選擇 1 名作為本次定向喚醒的目標。\n2、推薦命輪：選定喚醒體後，將自動選中該喚醒體的推薦命輪！\n3、喚醒機率UP：\n·每次通過喚醒獲取到SSR時，有33.33%的機率為本期選定的SSR喚醒體或推薦命輪，喚醒體與推薦命輪將平分UP機率。 \n·若本次喚醒獲取的SSR非本期選定的SSR喚醒體或命輪，則下次通過喚醒獲取的SSR必定為本期選定的SSR喚醒體或命輪。\n·若連續2次喚醒獲取到相同本期UP物品，則下次通過喚醒獲取的UP必定為另一本期UP物品。\n4、喚醒體與其推薦命輪一旦選定後，本期無法再更改定向喚醒對象。"
