  LanguageConfig_Task_Appoint_Rules_CN = {
    Text = "<Title:【派遣規則】>\n·守密人可以派遣喚醒體進行調查或研究任務，完成任務後可獲得相應的獎勵。\n·達到任務需求的派遣總等級才可成功派遣，每個任務至多可同時派遣4名喚醒體。\n·派遣總等級每超出任務需求20級，可獲得1份額外獎勵。\n·每個喚醒體同時只能承接一個派遣任務。若在任務途中取消派遣，可以快速釋放佔用的喚醒體，但將無法獲得該任務的獎勵。\n·守密人調查等級提升至20/30/40/50/60級時，可承接的派遣任務數額外+1。\n·注意：喚醒體本源形態不可派遣。"
