  LanguageConfig_TrinketAutoRefineStopByMaxTimeLimit_CN = {
    Text = "已完成 100 次轉錄，自動轉錄結束。"
  },
  LanguageConfig_TrinketAutoRefine_CN = {
    Text = "<Title:自動轉錄>\n·自動轉錄可以根據當前材料情況，至多進行 100 次轉錄。\n·自動轉錄時，如果轉錄結果中有 1 條未鎖定屬性強度為 8 ，自動轉錄終止。\n·材料不足時，自動轉錄停止。\n\n<Title:跳過>\n·自動轉錄時將顯示每一次轉錄結果，可以選擇跳過轉錄過程。跳過後，將直接顯示自動轉錄最終結果。"
  },
  LanguageConfig_TrinketAutoSelectTips_CN = {
    Text = "自動選擇：優先選用品質較低、等級較低的密契作為素材"
  },
  LanguageConfig_TrinketBatchUnbindComingSoon_CN = {
    Text = "一鍵析離功能即將開放"
  },
  LanguageConfig_TrinketBatchUnbindTitle_CN = {
    Text = "一鍵析離"
  },
  LanguageConfig_TrinketBindBonusDesc_CN = {
    Text = "結合後，密契主屬性額外提升{s1}！"
  },
  LanguageConfig_TrinketBindNoneSelectedTips_CN = {
    Text = "沒有可以結合的密契，請至少選擇一個。"
  },
  LanguageConfig_TrinketBindRuleDesc_CN = {
    Text = "<Title:密契結合>\n·守密人現在可以為喚醒體結合密契。\n·喚醒體每個位置可結合 1 個密契，總共 6 個。\n·結合後，每個位置上的密契主屬性額外提升 50%。\n·已結合的密契不會在「物資–密契」與「冶煉室」中出現。\n·編隊與喚醒體助戰中，如果沒有為喚醒體裝配密契，已結合的密契將被自動裝配。\n·強化已結合的密契部件不改變結合狀態，主屬性提升會根據強化後的狀態更新。\n\n<Title:密契析離>\n·修改或取消密契結合，需要在密契結合頁面中析離已結合的密契。\n·單個部件析離需要消耗 10 個同類型密契（不限位置）。\n·析離密契時，已使用的密契不會出現在素材選項中。"
  },
  LanguageConfig_TrinketBindSuccessTips_CN = {
    Text = "密契結合成功"
  },
  LanguageConfig_TrinketBind_CN = {Text = "結合"},
  LanguageConfig_TrinketChangeBindSuccessTips_CN = {
    Text = "密契結合修改成功"
  },
  LanguageConfig_TrinketChangeBind_CN = {Text = "結合"},
