  },
  LanguageConfig_TrinketChoosenTitle_CN = {
    Text = "選擇密契"
  },
  LanguageConfig_TrinketContrast_CN = {Text = "對比"},
  LanguageConfig_TrinketConversionLockOneOption_CN = {
    Text = "消耗「{s1}」補足殘本"
  },
  LanguageConfig_TrinketConversionNewEnries_CN = {
    Text = "新副屬性"
  },
  LanguageConfig_TrinketConversionOriEnries_CN = {
    Text = "原副屬性"
  },
  LanguageConfig_TrinketConversionReplace_CN = {Text = "替換"},
  LanguageConfig_TrinketConversionRuleTitle_CN = {
    Text = "規則說明"
  },
  LanguageConfig_TrinketConversionRule_CN = {
    Text = "<Title:轉錄>\n·轉錄可以更改密契副屬性的種類和數值、對主屬性的種類和數值沒有影響。\n·轉錄時、副屬性的種類可以與主屬性重複、副屬間的種類也可以重複。\n·轉錄時、副屬性將會獲得不同強度的數值。\n·守密人解鎖密契轉錄後、通過任何方式新獲得的密契都將自動免費轉錄一次。\n\n<Title:鎖定>\n·轉錄時、如果想保留某些副屬性、可以點擊副屬性旁的鎖定按鈕進行鎖定、上鎖副屬性的種類和數值在轉錄時將會進行保留。\n·最多可同時對兩個副屬性進行鎖定。\n·鎖定1條屬性時、需要額外消耗相應的「密契殘本」× 20；鎖定2條屬性時、需要額外消耗「追憶羽筆」× 10。\n·選擇鎖定1條屬性時、可以勾選「消耗追憶羽筆補足殘本」；勾選後、若當前「密契殘本」不足、將自動消耗相應數量的追憶羽筆進行轉錄。"
  },
  LanguageConfig_TrinketConversion_CN = {Text = "轉錄"},
  LanguageConfig_TrinketCopyRules_CN = {
    Text = "1、禁忌纂錄內通關關卡後可以獲得「密契」！\n2、不同推薦等級的關卡可以獲得不同數量的「密契」。\n·推薦等級 25 級的關卡可以獲得「密契」× 1。\n·推薦等級 35 級的關卡可以獲得「密契」× 2。\n·推薦等級 45 級的關卡可以獲得「密契」× 3。\n3、完成關卡挑戰後解鎖重現、重現可以立即獲得該關卡的任務報酬。每次重現需消耗等同於進行調查所需的「靈啡肽」。\n4、每通關一章調查事件就解鎖一個密契關卡。\n5、若三星通關高難度關卡、則較低難度的關卡挑戰進度會自動標記為三星通關。"
  },
