    Text = "1、幻衣獎勵將在第5次抽取時開始出現。第1 ~ 4抽時，幻衣獎勵的機率將根據未獲得獎勵的初始機率按比例分配到各項未獲得獎勵。\n2、獎池內的獎勵固定，已獲得的獎勵不會再次出現。未獲得獎勵的機率會發生變動，變動後的機率為「該獎勵的初始機率/（100%-已獲得獎勵的初始機率總和）」。\n3、以下為所有獎勵的具體機率展示，展示至四捨五入後的小數點第四位。"
