  LanguageConfig_WeekChallengeInstructions_CN = {
    Text = "<Title:【無光之境】>\n·「無光之境」是一系列高難度調查關卡。守密人戰勝最終首領完成調查後、可領取豐厚的調查獎勵。守密人在「無光之境」的挑戰不會消耗「靈啡肽」。\n\n<Title:【挑戰規則】>\n·守密人戰勝密境最終首領完成調查後、可以獲取相應星級的調查評價。隨著調查評分星級的提升、可以獲得不同的獎勵。\n·在不同的「無光之境」關卡中、守密人會獲得獨特的初始造物支持、僅在當前「無光之境」關卡內生效。\n·在同一「無光之境」關卡中、守密人成功通關某一密境關卡後、將記錄當前編隊所使用的喚醒體。相同的喚醒體無法在其他密境關卡中上場。\n·守密人可對已經通關的密境關卡進行進度重置、重置後該密境下通關使用的角色以及星級記錄將會被清除、守密人可重新進行編隊調整並繼續挑戰。"
  },
